-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (10112, 23, 'Präventionsprogramme gegen Mobbing, Gewalt und Ausgrenzung an Schulen fördern (Land)', 'Schulische Anti-Mobbing-Programme senken Mobbing und Viktimisierung nachweislich, wenn auch moderat; die Zusagen bleiben unbestimmt (fördern, stärken) und legen weder Reichweite noch Programmstandard fest.', 'belegt', 'https://doi.org/10.1002/cl2.1143', 'land', null, true, 'blind', null),
  (10113, 23, 'Flächendeckende, verbindliche Präventions- und Anti-Gewaltprogramme an allen Schulen (Land)', 'Setzt direkt an Klassennormen an; Meta-Analysen zeigen eine Senkung von Mobbing um rund ein Fünftel. Flächendeckende Einführung braucht Fortbildung, Unterrichtszeit und Qualitätssicherung über Jahre.', 'belegt', 'https://doi.org/10.1002/cl2.1143', 'land', null, true, 'blind', null),
  (10114, 23, 'Soziales Lernen, Empathie und Konfliktlösung als Unterrichtsinhalt stärken (Land)', 'Programme zum sozial-emotionalen Lernen verbessern belegt Sozialverhalten und Klassenklima; Wirkung auf Mobbing selbst ist schwächer belegt und hängt von Umsetzung und Programmqualität ab.', 'belegt', 'https://doi.org/10.1111/j.1467-8624.2010.01564.x', 'land', null, true, 'blind', null),
  (10115, 23, 'Aufklärung gegen Diskriminierung und queerfeindliche Haltungen in der Schule (Land)', 'Zielt auf abwertende Haltungen, die Ausgrenzung begünstigen; Programme zur Vorurteilsreduktion zeigen aber oft nur kleine, kurzlebige Effekte, eine Wirkung auf Mobbing ist kaum nachgewiesen.', 'gemischt', null, 'land', null, true, 'blind', null),
  (10116, 23, 'Klassengemeinschaft stärken: Klassenrat, Klassenleiterstunde, gemeinsame Aktivitäten (Land)', 'Kann Zusammenhalt und Klassennormen positiv beeinflussen und Konflikte früh sichtbar machen; eigenständige Wirkung auf Mobbing ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind', null),
  (10117, 23, 'Zusätzliche Lernzeit mit sozialem Lernen in Vorschule und Ganztag (Land)', 'Soziales Lernen ist nur ein Nebenziel von Vorschule und Ganztag; ein Effekt auf Mobbing in der Schule ist kaum untersucht. Ausbau braucht Personal und Räume.', 'offen', null, 'land', null, true, 'blind', null),
  (10118, 23, 'Verpflichtende Schutzkonzepte gegen Gewalt und Diskriminierung an Schulen (Land)', 'Schutzkonzepte schaffen Interventionspläne, Beschwerdewege und Prävention; Länder können sie vorschreiben. Wirkung auf Mobbing unter Schülern ist kaum evaluiert, Qualität hängt von der Umsetzung ab.', 'offen', null, 'land', null, true, 'blind', null),
  (10119, 23, 'Schutzkonzepte in Einrichtungen für Kinder fördern oder vorschreiben (Bund)', 'Bund kann über Kinder- und Jugendhilfe und Anreize beitragen, für Schulen sind aber die Länder zuständig; Wirkung auf Mobbing unter Schülern ist kaum untersucht.', 'offen', null, 'bund', null, true, 'blind', null),
  (10120, 23, 'Klare Schulregeln zu Gewalt und Mobbing mit verbindlichen, abgestuften Reaktionen (Land)', 'Klare Regeln und verlässliche Reaktionen gelten als wirksame Bestandteile von Anti-Mobbing-Programmen; rein strafende Ahndung ohne Prävention zeigt dagegen wenig Wirkung auf das Schulklima.', 'gemischt', null, 'land', null, true, 'blind', null),
  (10121, 23, 'Schulverweise und alternative Beschulung bei Gewalt erleichtern (Land)', 'Schützt Mitschüler kurzfristig vor gewalttätigen Einzelnen; Studien zu Ausschlüssen finden aber keine Verbesserung von Schulklima und Verhalten, teils mehr Folgeprobleme bei den Ausgeschlossenen.', 'gemischt', null, 'land', null, true, 'blind', null),
  (10122, 23, 'Schulsozialarbeit und Schulpsychologie an jeder Schule ausbauen (Land)', 'Fachkräfte vor Ort können Konflikte und Mobbingfälle früh bearbeiten und Lehrkräfte unterstützen; belastbare Wirkungsstudien fehlen weitgehend, und Fachkräfte sind knapp.', 'offen', null, 'land', null, true, 'blind', null),
  (10123, 23, 'Psychologische und psychosoziale Unterstützung für Schüler an Schulen ausbauen (Land)', 'Hilft Belasteten, lindert aber Folgen statt den Leistungsdruck selbst; gezielte Hilfen wirken, universelle Programme (etwa Achtsamkeit) zeigten in großen Studien keinen Effekt.', 'gemischt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9340028/', 'land', null, true, 'blind', null),
  (10124, 23, 'Psychosoziale Fachkräfte und Mental-Health-Angebote an Schulen fördern (Bund)', 'Bund kann mit Programmen beitragen, dauerhaftes Personal an Schulen liegt bei den Ländern; lindert Folgen von Druck, universelle Angebote zeigen gemischte Ergebnisse.', 'gemischt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9340028/', 'bund', null, true, 'blind', null),
  (10125, 23, 'Fortbildung von Lehrkräften zu Mobbing, Gewalt, Konflikten und Klassenführung (Land)', 'Aktives Eingreifen von Lehrkräften hängt mit weniger Viktimisierung zusammen; eine kontrollierte Studie zu einem kurzen Lehrkräftetraining fand aber keine Änderung von Verhalten und Mobbing.', 'gemischt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10603241/', 'land', null, true, 'blind', null),
  (10126, 23, 'Lehrkräfteaus- und -fortbildung allgemein praxisnäher und verbindlicher gestalten (Land)', 'Mehr Praxis und Fortbildung können die Handlungssicherheit im Klassenraum stärken; Mobbing und Konflikte sind nicht genannt, ein Effekt auf das Eingreifen ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind', null),
  (10127, 23, 'Fortbildungen für pädagogische Fachkräfte zu Diskriminierung (Land)', 'Kann Lehrkräfte für Ausgrenzung sensibilisieren; ob Diskriminierungsfortbildungen das Eingreifen bei Mobbing verändern, ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind', null),
  (10128, 23, 'Unabhängige Beschwerdestellen für Schülerinnen, Schüler und Eltern (Land)', 'Bietet Betroffenen einen Weg, wenn die Schule nicht handelt; wirkt aber nachgelagert im Einzelfall, Effekte auf Mobbing sind kaum untersucht.', 'offen', null, 'land', null, true, 'blind', null),
  (10129, 23, 'Lehrpläne und Stundentafel entschlacken (Land)', 'Weniger Stoff und Fächer können Lernlast senken; ob der Leistungsdruck dadurch spürbar sinkt, hängt von Prüfungen und Bewertung ab und ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind', null),
  (10130, 23, 'Längeres gemeinsames Lernen und weniger Selektionsdruck beim Übergang (Land)', 'Verbindliche Übergangsentscheidungen erhöhen nachweislich Noten- und Zukunftsangst in Klasse 4; zugleich steigen dort die Leistungen. Strukturreformen brauchen mehrere Jahre.', 'gemischt', 'https://www.zew.de/en/press/latest-press-releases/binding-teachers-recommendation-for-secondary-school-track-increases-pupils-achievement-but-also-their-stress-levels', 'land', null, true, 'blind', null),
  (10131, 23, 'Hausaufgaben in die betreute Schulzeit verlagern (Land)', 'Mehr Hausaufgabenzeit geht mit mehr Lernangst einher (Querschnittsdaten); der Nutzen von Hausaufgaben ist uneinheitlich belegt. Betreute Lernzeit braucht Personal.', 'gemischt', 'https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2023.1130274/full', 'land', null, true, 'blind', null),
  (10132, 23, 'Jugendschutz auf Plattformen durchsetzen, etwa durch Altersverifikation (Bund)', 'Plattformpflichten können Kinder vor Angriffen schützen; Wirkung auf Cybermobbing ist nicht belegt, Altersprüfungen werden umgangen, und vieles hängt vom EU-Rahmen (DSA) ab.', 'offen', null, 'bund', null, true, 'blind', null),
  (10320, 23, 'Pflichtweises Sitzenbleiben abschaffen, Wiederholen nur noch freiwillig (Land)', 'Nimmt die Drohung der Nichtversetzung, und Sitzenbleiben verbessert Leistungen laut Forschung nicht; zum Wohlbefinden sind Befunde uneinheitlich (teils Belastung, teils positive Effekte), betroffen ist ein kleiner Teil.', 'gemischt', 'https://www.bertelsmann-stiftung.de/de/publikationen/publikation/did/klassenwiederholungen-teuer-und-unwirksam', 'land', null, true, 'blind', null),
  (10321, 23, 'Ziffernnoten weitgehend durch schriftliche oder dialogische Rückmeldungen ersetzen (Land)', 'Benotete Stunden gehen in Studien mit mehr Angst und weniger Motivation einher; in Langzeitvergleichen ohne Noten zeigte sich aber kaum besseres Wohlbefinden, Druck kann sich auf spätere Abschlüsse verlagern.', 'gemischt', 'https://publinova.nl/product/performance-grading-and-motivational-functioning-and-fear-in-physical-education', 'land', null, true, 'blind', null),
  (10322, 23, 'Mentale Gesundheit, Resilienz und Stressbewältigung im Unterricht verankern (Land)', 'Schulische Präventionsprogramme senken Angst und Depressivität nur schwach, universelle Angebote weniger als gezielte; lindert Folgen, statt den Leistungsdruck selbst zu senken. Curricula sind Landessache.', 'gemischt', 'https://openresearch-repository.anu.edu.au/items/f894e732-2981-4864-b78f-eafbf446aba1', 'land', null, true, 'blind', null),
  (10323, 23, 'Ruhe- und Rückzugsräume ohne Bewertung und Pausengestaltung an Schulen (Land)', 'Kann Erholung im Schulalltag ermöglichen; berührt den Leistungsdruck nur am Rand, Wirkung kaum untersucht, und Räume fehlen an vielen Schulen.', 'offen', null, 'land', null, true, 'blind', null),
  (10324, 23, 'Selektionshürden beim Übergang zur weiterführenden Schule abbauen (Empfehlung, Probeunterricht) (Land)', 'Verbindliche Übergangsentscheidungen erhöhen nachweislich Sorgen in Klasse 4, zugleich steigen dort die Leistungen; die Maßnahmen lockern nur einzelne Hürden, Druck kann sich auf später verlagern.', 'gemischt', 'https://www.zew.de/en/press/latest-press-releases/binding-teachers-recommendation-for-secondary-school-track-increases-pupils-achievement-but-also-their-stress-levels', 'land', null, true, 'blind', null)
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft,
  nebenwirkungen = excluded.nebenwirkungen;

delete from public.instrumente where thema_id = 23 and id not in (10112, 10113, 10114, 10115, 10116, 10117, 10118, 10119, 10120, 10121, 10122, 10123, 10124, 10125, 10126, 10127, 10128, 10129, 10130, 10131, 10132, 10320, 10321, 10322, 10323, 10324);

insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (10133, 23, 11, null, 'Ausreichenden Kinder- und Jugendschutz im Internet gewährleisten; Digital Services Act mit Schwerpunkt Jugend- und Medienschutz umsetzen', '{2303}', 10132, 1, 2, null, 'Plattformpflichten können Kinder vor Angriffen schützen; Wirkung auf Cybermobbing ist nicht belegt, Altersprüfungen werden umgangen, und vieles hängt vom EU-Rahmen (DSA) ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=41', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10134, 23, 11, null, 'Verbindliche, standardisierte Schutzkonzepte dort, wo Kinder betreut werden (Gewaltprävention)', '{2301}', 10119, 1, 2, null, 'Bund kann über Kinder- und Jugendhilfe und Anreize beitragen, für Schulen sind aber die Länder zuständig; Wirkung auf Mobbing unter Schülern ist kaum untersucht.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=39', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10135, 23, 11, 'BE', 'Gewaltfreie Konfliktlösung sowie Gleichberechtigung und Grenzen früh in Kitas und Schulen vermitteln', '{2301}', 10114, 2, 3, null, 'Programme zum sozial-emotionalen Lernen verbessern belegt Sozialverhalten und Klassenklima; Wirkung auf Mobbing selbst ist schwächer belegt und hängt von Umsetzung und Programmqualität ab.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=11', 'https://doi.org/10.1111/j.1467-8624.2010.01564.x', 'belegt', '2026-10-20', false, true, 'blind', null),
  (10136, 23, 11, 'BE', 'Ganztagsangebote an Grundschulen qualitativ ausbauen; sie sollen unter anderem soziales Lernen fördern', '{2301}', 10117, 1, 2, null, 'Soziales Lernen ist nur ein Nebenziel von Vorschule und Ganztag; ein Effekt auf Mobbing in der Schule ist kaum untersucht. Ausbau braucht Personal und Räume.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=56', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10137, 23, 11, 'BE', 'Gesetzliche Schutzpflicht an Schulen, damit Schülerinnen und Schüler vor religiösem oder sozialem Gruppendruck geschützt sind', '{2301}', null, 1, 2, null, 'Benennt Gruppendruck unter Schülern als Schutzgut; eine gesetzliche Schutzpflicht ohne konkrete Instrumente wirkt kaum im Alltag und berührt Grundrechtsabwägungen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=57', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10138, 23, 11, 'BE', 'Aus-, Fort- und Weiterbildung von Lehrkräften verbindlicher ausrichten; alle Lehrkräfte sollen regelmäßig fortgebildet werden', '{2302}', 10126, 1, 3, null, 'Mehr Praxis und Fortbildung können die Handlungssicherheit im Klassenraum stärken; Mobbing und Konflikte sind nicht genannt, ein Effekt auf das Eingreifen ist kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=58', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10139, 23, 11, 'BE', 'Strategie gegen Gewalt an Schulen, die Prävention, Intervention und Repression konsequent verbindet', '{2302,2301}', null, 1, 3, null, 'Verbindet Prävention und Intervention, was erfolgreiche Ansätze auszeichnet; es bleibt aber bei der Ankündigung einer Strategie ohne konkrete Instrumente.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=60', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10140, 23, 11, 'BE', 'Landesprogramm für psychische Gesundheit und Ausbau schulpsychologischer Angebote, Resilienzförderung im Schulalltag', '{2304}', 10123, 1, 2, null, 'Hilft Belasteten, lindert aber Folgen statt den Leistungsdruck selbst; gezielte Hilfen wirken, universelle Programme (etwa Achtsamkeit) zeigten in großen Studien keinen Effekt.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=61', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9340028/', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10141, 23, 11, 'MV', 'Gezieltes Mentoring für angehende Lehrkräfte beim Berufseinstieg', '{2302}', 10126, 1, 3, null, 'Mehr Praxis und Fortbildung können die Handlungssicherheit im Klassenraum stärken; Mobbing und Konflikte sind nicht genannt, ein Effekt auf das Eingreifen ist kaum untersucht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=56', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10142, 23, 11, 'MV', 'Lehramtsausbildung durch mehr und früher beginnende Praxisphasen im Studium praxisnäher gestalten', '{2302}', 10126, 1, 3, null, 'Mehr Praxis und Fortbildung können die Handlungssicherheit im Klassenraum stärken; Mobbing und Konflikte sind nicht genannt, ein Effekt auf das Eingreifen ist kaum untersucht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=55', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10143, 23, 11, 'ST', 'Ausbildung von Lehrkräften auf Praxisnähe ausrichten, mehr verbindliche Praxisphasen', '{2302}', 10126, 1, 3, null, 'Mehr Praxis und Fortbildung können die Handlungssicherheit im Klassenraum stärken; Mobbing und Konflikte sind nicht genannt, ein Effekt auf das Eingreifen ist kaum untersucht.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=25', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10144, 23, 11, 'ST', 'Oberschule: Stärkung von Basiskompetenzen, Sozialverhalten und Selbstorganisation', '{2301}', 10114, 2, 3, null, 'Programme zum sozial-emotionalen Lernen verbessern belegt Sozialverhalten und Klassenklima; Wirkung auf Mobbing selbst ist schwächer belegt und hängt von Umsetzung und Programmqualität ab.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=22', 'https://doi.org/10.1111/j.1467-8624.2010.01564.x', 'belegt', '2026-10-20', false, true, 'blind', null),
  (10145, 23, 12, null, 'Anreize für Schutzkonzepte gegen Gewalt in Einrichtungen, in denen Kinder und Jugendliche sich aufhalten', '{2302}', 10119, 1, 2, null, 'Bund kann über Kinder- und Jugendhilfe und Anreize beitragen, für Schulen sind aber die Länder zuständig; Wirkung auf Mobbing unter Schülern ist kaum untersucht.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=28', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10146, 23, 12, null, 'Jugendschutz im Netz stärken, etwa durch Möglichkeiten zur Altersverifikation', '{2303}', 10132, 1, 2, null, 'Plattformpflichten können Kinder vor Angriffen schützen; Wirkung auf Cybermobbing ist nicht belegt, Altersprüfungen werden umgangen, und vieles hängt vom EU-Rahmen (DSA) ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=45', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10147, 23, 12, 'BE', 'Jede Schule soll ein Anti-Mobbing-Team bekommen, das gegen Mobbing vorgeht.', '{2302}', null, 2, 2, null, 'Feste Teams bearbeiten Mobbingfälle verlässlich, wie in erfolgreichen Programmen (etwa KiVa); als Einzelmaßnahme kaum evaluiert, und Teams brauchen Zeit und Schulung.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10148, 23, 12, 'BE', 'Mehr Stellen für Schulsozialarbeit und Schulpsychologie sowie weitere Fachkräfte, auch gegen Mobbing und Konflikte.', '{2301,2302}', 10122, 2, 2, null, 'Fachkräfte vor Ort können Konflikte und Mobbingfälle früh bearbeiten und Lehrkräfte unterstützen; belastbare Wirkungsstudien fehlen weitgehend, und Fachkräfte sind knapp.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10149, 23, 12, 'BE', 'Eine unabhängige Beschwerdestelle für Schulen und Kitas beim Parlament ansiedeln.', '{2302}', 10128, 1, 3, null, 'Bietet Betroffenen einen Weg, wenn die Schule nicht handelt; wirkt aber nachgelagert im Einzelfall, Effekte auf Mobbing sind kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10150, 23, 12, 'BE', 'Das Thema Empathie als Wahlpflichtfach einführen, um Mitgefühl und Kompromissfähigkeit zu fördern.', '{2301}', 10114, 2, 3, null, 'Programme zum sozial-emotionalen Lernen verbessern belegt Sozialverhalten und Klassenklima; Wirkung auf Mobbing selbst ist schwächer belegt und hängt von Umsetzung und Programmqualität ab.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', 'https://doi.org/10.1111/j.1467-8624.2010.01564.x', 'belegt', '2026-10-20', false, true, 'blind', null),
  (10151, 23, 12, 'BE', 'Queere Bildung in Schulen stärken, um Hass und Gewalt vorzubeugen.', '{2301}', 10115, 1, 3, null, 'Zielt auf abwertende Haltungen, die Ausgrenzung begünstigen; Programme zur Vorurteilsreduktion zeigen aber oft nur kleine, kurzlebige Effekte, eine Wirkung auf Mobbing ist kaum nachgewiesen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=49', null, 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10152, 23, 12, 'BE', 'Rahmenlehrpläne verschlanken und die Stundentafel flexibilisieren, ohne weitere Fächer einzuführen.', '{2304}', 10129, 1, 3, null, 'Weniger Stoff und Fächer können Lernlast senken; ob der Leistungsdruck dadurch spürbar sinkt, hängt von Prüfungen und Bewertung ab und ist kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=40', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10153, 23, 12, 'BE', 'Mentale Gesundheit aller Beteiligten an Schulen stärken, mit mehr Schulpsychologie und Gesundheitsfachkräften.', '{2304}', 10123, 1, 2, null, 'Hilft Belasteten, lindert aber Folgen statt den Leistungsdruck selbst; gezielte Hilfen wirken, universelle Programme (etwa Achtsamkeit) zeigten in großen Studien keinen Effekt.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=42', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9340028/', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10154, 23, 12, 'BE', 'Fortbildungen zu Diskriminierung und Rassismus; diskriminierungskritische Module in der Ausbildung pädagogischer Fachkräfte.', '{2302}', 10127, 1, 3, null, 'Kann Lehrkräfte für Ausgrenzung sensibilisieren; ob Diskriminierungsfortbildungen das Eingreifen bei Mobbing verändern, ist kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10155, 23, 12, 'MV', 'Präventionsangebote gegen Mobbing, Gewalt und Ausgrenzung weiter unterstützen; Angebote zur Stärkung psychischer Gesundheit junger Menschen.', '{2301}', 10112, 2, 3, null, 'Schulische Anti-Mobbing-Programme senken Mobbing und Viktimisierung nachweislich, wenn auch moderat; die Zusagen bleiben unbestimmt (fördern, stärken) und legen weder Reichweite noch Programmstandard fest.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=36', 'https://doi.org/10.1002/cl2.1143', 'belegt', '2026-10-20', false, true, 'blind', null),
  (10156, 23, 12, 'MV', 'Konfliktlösung und Kommunikation als Alltagskompetenzen in der schulischen Bildung stärken.', '{2301}', 10114, 2, 3, null, 'Programme zum sozial-emotionalen Lernen verbessern belegt Sozialverhalten und Klassenklima; Wirkung auf Mobbing selbst ist schwächer belegt und hängt von Umsetzung und Programmqualität ab.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=69', 'https://doi.org/10.1111/j.1467-8624.2010.01564.x', 'belegt', '2026-10-20', false, true, 'blind', null),
  (10157, 23, 12, 'MV', 'Leistungsbewertung reformieren, mit lernförderlichen und prozessorientierten Rückmeldungen.', '{2304}', null, 1, 3, null, 'Lernförderliche Rückmeldungen können Bewertungsangst mindern; ohne Änderung an Abschlüssen und Übergängen bleibt der Druck, die Befundlage zu notenfreier Bewertung ist uneinheitlich.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=68', null, 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10158, 23, 12, 'MV', 'In der beruflichen Ausbildung ein flexibleres Prüfungssystem mit mehreren Prüfungszeiträumen schaffen.', '{2304}', null, 1, 2, null, 'Mehrere Prüfungstermine können Prüfungsstress in der Ausbildung mindern; kaum untersucht, und der Spielraum ist durch bundesweite Prüfungsordnungen begrenzt.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=70', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10159, 23, 12, 'ST', 'Präventions- und Demokratieprojekte an Schulen gegen abwertende Haltungen unter Schülern verstärkt und dauerhaft fördern.', '{2301}', 10112, 2, 3, null, 'Schulische Anti-Mobbing-Programme senken Mobbing und Viktimisierung nachweislich, wenn auch moderat; die Zusagen bleiben unbestimmt (fördern, stärken) und legen weder Reichweite noch Programmstandard fest.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=36', 'https://doi.org/10.1002/cl2.1143', 'belegt', '2026-10-20', false, true, 'blind', null),
  (10160, 23, 12, 'ST', 'Schulen und andere Einrichtungen sollen verpflichtend Schutzkonzepte gegen Gewalt und Diskriminierung entwickeln und umsetzen.', '{2301}', 10118, 2, 3, null, 'Schutzkonzepte schaffen Interventionspläne, Beschwerdewege und Prävention; Länder können sie vorschreiben. Wirkung auf Mobbing unter Schülern ist kaum evaluiert, Qualität hängt von der Umsetzung ab.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=32', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10161, 23, 12, 'ST', 'Präventionsangebote in Kommunen und Schulen unterstützen, um Konflikte frühzeitig zu entschärfen.', '{2301}', null, 1, 3, null, 'Allgemeine kommunale Kriminalprävention kann Konflikte entschärfen; Schule und Mobbing sind nur ein Teilbereich, Wirkung auf das Klassenklima ist offen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=30', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10162, 23, 12, 'ST', 'Verbindliche regelmäßige Schulungen und Fortbildungen für Fachkräfte in der Gewalt- und Diskriminierungsprävention.', '{2302}', 10125, 2, 3, null, 'Aktives Eingreifen von Lehrkräften hängt mit weniger Viktimisierung zusammen; eine kontrollierte Studie zu einem kurzen Lehrkräftetraining fand aber keine Änderung von Verhalten und Mobbing.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=33', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10603241/', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10163, 23, 12, 'ST', 'Qualifizierung zu Beratungslehrkräften neu starten.', '{2302}', 10125, 2, 3, null, 'Aktives Eingreifen von Lehrkräften hängt mit weniger Viktimisierung zusammen; eine kontrollierte Studie zu einem kurzen Lehrkräftetraining fand aber keine Änderung von Verhalten und Mobbing.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10603241/', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10164, 23, 13, null, 'Mental-Health-Coaches und Gruppenangebote an weiterführenden Schulen ausbauen, Schwerpunkt Schulen mit besonderen Bedarfen.', '{2304}', 10124, 1, 2, null, 'Bund kann mit Programmen beitragen, dauerhaftes Personal an Schulen liegt bei den Ländern; lindert Folgen von Druck, universelle Angebote zeigen gemischte Ergebnisse.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=85', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9340028/', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10165, 23, 13, null, 'Diskriminierungssensible Fortbildungen in Kindertagespflege und Lehrkräfteausbildung fördern.', '{2302}', null, 1, 2, null, 'Sensibilisierung kann Ausgrenzung früher erkennen lassen; Effekt auf Eingreifen bei Mobbing kaum untersucht, Lehrkräfteausbildung liegt bei den Ländern, der Bund kann nur fördern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=76', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10166, 23, 13, 'BE', 'Klassenräte sollen an allen Schulen und in allen Klassen verbindlich umgesetzt werden.', '{2301}', 10116, 1, 3, null, 'Kann Zusammenhalt und Klassennormen positiv beeinflussen und Konflikte früh sichtbar machen; eigenständige Wirkung auf Mobbing ist kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=185', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10167, 23, 13, 'BE', 'Unabhängige Beschwerdestelle gegen Diskriminierung an Schulen wird eingerichtet.', '{2302}', 10128, 1, 3, null, 'Bietet Betroffenen einen Weg, wenn die Schule nicht handelt; wirkt aber nachgelagert im Einzelfall, Effekte auf Mobbing sind kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=136', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10168, 23, 13, 'BE', 'Bedarfsgerechte, qualitätsgesicherte Fortbildungen für pädagogisches Personal, schulweit umgesetzt und evaluiert.', '{2302}', 10126, 1, 3, null, 'Mehr Praxis und Fortbildung können die Handlungssicherheit im Klassenraum stärken; Mobbing und Konflikte sind nicht genannt, ein Effekt auf das Eingreifen ist kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=194', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10169, 23, 13, 'BE', 'Kinderschutzstandards sollen in allen Einrichtungen, in denen sich Kinder und Jugendliche aufhalten, verlässlich umgesetzt werden.', '{2302}', 10118, 2, 3, null, 'Schutzkonzepte schaffen Interventionspläne, Beschwerdewege und Prävention; Länder können sie vorschreiben. Wirkung auf Mobbing unter Schülern ist kaum evaluiert, Qualität hängt von der Umsetzung ab.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=184', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10170, 23, 13, 'BE', 'Zahl der Gemeinschaftsschulen soll verdoppelt werden, um Schulstress zu verringern.', '{2304}', 10130, 2, 2, null, 'Verbindliche Übergangsentscheidungen erhöhen nachweislich Noten- und Zukunftsangst in Klasse 4; zugleich steigen dort die Leistungen. Strukturreformen brauchen mehrere Jahre.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=220', 'https://www.zew.de/en/press/latest-press-releases/binding-teachers-recommendation-for-secondary-school-track-increases-pupils-achievement-but-also-their-stress-levels', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10171, 23, 13, 'BE', 'Verlässliche Betreuung in der Grundschule wird um mindestens eine Stunde verlängert, damit zu Hause keine Aufgaben mehr nötig sind.', '{2304}', 10131, 1, 2, null, 'Mehr Hausaufgabenzeit geht mit mehr Lernangst einher (Querschnittsdaten); der Nutzen von Hausaufgaben ist uneinheitlich belegt. Betreute Lernzeit braucht Personal.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=191', 'https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2023.1130274/full', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10172, 23, 13, 'BE', 'Der Übergang von der Grund- zur Oberschule soll reformiert werden, damit Schüler*innen mit weniger Druck zur Schule gehen.', '{2304}', 10130, 2, 2, null, 'Verbindliche Übergangsentscheidungen erhöhen nachweislich Noten- und Zukunftsangst in Klasse 4; zugleich steigen dort die Leistungen. Strukturreformen brauchen mehrere Jahre.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=188', 'https://www.zew.de/en/press/latest-press-releases/binding-teachers-recommendation-for-secondary-school-track-increases-pupils-achievement-but-also-their-stress-levels', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10173, 23, 13, 'BE', 'Präventions- und Unterstützungsangebote für Kinder und Jugendliche sollen deutlich ausgebaut werden, unter anderem mit mehr Schulpsychologie.', '{2304}', 10123, 1, 2, null, 'Hilft Belasteten, lindert aber Folgen statt den Leistungsdruck selbst; gezielte Hilfen wirken, universelle Programme (etwa Achtsamkeit) zeigten in großen Studien keinen Effekt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=204', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9340028/', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10174, 23, 13, 'MV', 'Medienbildung für Lehrkräfte stärken, damit Schulen besser auf Mobbing im Netz reagieren können', '{2302}', 10125, 2, 3, null, 'Aktives Eingreifen von Lehrkräften hängt mit weniger Viktimisierung zusammen; eine kontrollierte Studie zu einem kurzen Lehrkräftetraining fand aber keine Änderung von Verhalten und Mobbing.', 'https://gruene-mv.de/?wpdmdl=33772#page=44', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10603241/', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10175, 23, 13, 'MV', 'Psychosoziale Beratung an Schulen ermöglichen und Programme für die mentale Gesundheit von Schüler*innen ausbauen', '{2304}', 10123, 1, 2, null, 'Hilft Belasteten, lindert aber Folgen statt den Leistungsdruck selbst; gezielte Hilfen wirken, universelle Programme (etwa Achtsamkeit) zeigten in großen Studien keinen Effekt.', 'https://gruene-mv.de/?wpdmdl=33772#page=44', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9340028/', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10176, 23, 13, 'MV', 'Stundentafel entschlacken und Fächerzahl reduzieren', '{2304}', 10129, 1, 3, null, 'Weniger Stoff und Fächer können Lernlast senken; ob der Leistungsdruck dadurch spürbar sinkt, hängt von Prüfungen und Bewertung ab und ist kaum untersucht.', 'https://gruene-mv.de/?wpdmdl=33772#page=43', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10177, 23, 13, 'MV', 'Wahlmöglichkeiten zwischen Abitur nach zwölf oder dreizehn Jahren an Schulen schaffen', '{2304}', null, 1, 2, null, 'Längere Schulzeit kann Zeitdruck mindern; Studien zu G8/G9 finden teils mehr Stress bei G8 (v. a. Mädchen), teils keine gesundheitlichen Unterschiede. Wahlmodell braucht Organisationsaufwand.', 'https://gruene-mv.de/?wpdmdl=33772#page=43', 'https://www.diw.de/de/diw_01.c.497179.de/publikationen/roundup/2015_0057/empirische_befunde_zu_auswirkungen_der_g8-schulzeitverkuerzung.html', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10178, 23, 13, 'MV', 'Präventionskonzepte gegen sexualisierte und digitale Gewalt an Schulen', '{2301}', 10112, 2, 3, null, 'Schulische Anti-Mobbing-Programme senken Mobbing und Viktimisierung nachweislich, wenn auch moderat; die Zusagen bleiben unbestimmt (fördern, stärken) und legen weder Reichweite noch Programmstandard fest.', 'https://gruene-mv.de/?wpdmdl=33772#page=82', 'https://doi.org/10.1002/cl2.1143', 'belegt', '2026-10-20', false, true, 'blind', null),
  (10179, 23, 13, 'MV', 'Fachkräfte durch gezielte Fortbildungen unterstützen, Kinder und Jugendliche schutzorientiert zu begleiten', '{2302}', 10127, 1, 3, null, 'Kann Lehrkräfte für Ausgrenzung sensibilisieren; ob Diskriminierungsfortbildungen das Eingreifen bei Mobbing verändern, ist kaum untersucht.', 'https://gruene-mv.de/?wpdmdl=33772#page=84', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10180, 23, 13, 'MV', 'Verpflichtende Weiterbildungen für Pädagog*innen gegen Mehrfachdiskriminierung queerer Menschen einführen', '{2302}', 10127, 1, 3, null, 'Kann Lehrkräfte für Ausgrenzung sensibilisieren; ob Diskriminierungsfortbildungen das Eingreifen bei Mobbing verändern, ist kaum untersucht.', 'https://gruene-mv.de/?wpdmdl=33772#page=87', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10181, 23, 14, null, 'Praxisnahe Aus- und Fortbildung sowie bessere Arbeitsbedingungen und Aufstieg für Lehrkräfte', '{2302}', null, 1, 1, null, 'Bessere Ausbildung kann Handlungssicherheit stärken, Mobbing ist nicht genannt; Lehrkräfteausbildung und Bezahlung liegen bei den Ländern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10182, 23, 14, null, 'Auseinandersetzung mit Menschenfeindlichkeit im Schulunterricht intensivieren', '{2301}', null, 1, 1, null, 'Kann abwertende Haltungen thematisieren; Wirkung auf Mobbing ist schwach belegt, und Unterrichtsinhalte regeln allein die Länder.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', null, 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10183, 23, 14, null, 'Schulen erhalten frei einsetzbares Budget und können auch über die Länge der gymnasialen Laufbahn entscheiden', '{2304}', null, 1, 1, null, 'Wahl der Schulzeit kann Zeitdruck mindern, Befunde zu G8/G9 sind gemischt; Schulautonomie und Schulzeit regeln die Länder, der Bund kann das nicht vorgeben.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', null, 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10184, 23, 14, 'BE', 'Verpflichtende, bedarfsgerechte Fortbildungen für alle Lehrkräfte mit jährlichem Mindestkontingent und regelmäßiger Kontrolle.', '{2302}', 10126, 1, 3, null, 'Mehr Praxis und Fortbildung können die Handlungssicherheit im Klassenraum stärken; Mobbing und Konflikte sind nicht genannt, ein Effekt auf das Eingreifen ist kaum untersucht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=10', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10185, 23, 14, 'BE', 'Polizeiliche Anti-Gewalt-Trainings im Schulunterricht und Informationsangebote ausbauen.', '{2301}', null, 1, 3, null, 'Ergänzt Prävention im Unterricht; polizeilich geleitete Kurzprogramme zeigen in Studien meist nur schwache Effekte, Mobbing wird nicht eigens adressiert.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=68', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10186, 23, 14, 'BE', 'Mehr Einsatz von Jugend- und Sozialarbeit und eine bessere Verzahnung von Polizei, Schulen und Jugendhilfe.', '{2302}', null, 1, 2, null, 'Bessere Zusammenarbeit von Schule, Jugendhilfe und Polizei kann bei Gewalt schneller Hilfe bringen; vieles zielt auf Jugendkriminalität außerhalb der Schule, Wirkung auf Mobbing ist offen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=68', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10187, 23, 14, 'MV', 'Prävention von Mobbing, Cybermobbing und Gewalt an Schulen stärken', '{2301}', 10112, 2, 3, null, 'Schulische Anti-Mobbing-Programme senken Mobbing und Viktimisierung nachweislich, wenn auch moderat; die Zusagen bleiben unbestimmt (fördern, stärken) und legen weder Reichweite noch Programmstandard fest.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=87', 'https://doi.org/10.1002/cl2.1143', 'belegt', '2026-10-20', false, true, 'blind', null),
  (10188, 23, 14, 'MV', 'Schulordnungen mit klaren Regeln zu Gewalt und Mobbing und abgestuften Reaktionswegen', '{2301}', 10120, 2, 3, null, 'Klare Regeln und verlässliche Reaktionen gelten als wirksame Bestandteile von Anti-Mobbing-Programmen; rein strafende Ahndung ohne Prävention zeigt dagegen wenig Wirkung auf das Schulklima.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=89', null, 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10189, 23, 14, 'MV', 'Vom Unterricht suspendierte, gewaltauffällige Jugendliche durch Bildungs- und Berufsangebote beschäftigen und fördern', '{2301}', null, 1, 2, null, 'Förderung suspendierter Jugendlicher kann Rückfälle verringern; setzt erst nach dem Ausschluss an und wirkt kaum auf das Klima in der Klasse.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=89', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10190, 23, 14, 'MV', 'Fortbildungen für Lehrkräfte zum Umgang mit Gewaltvorfällen verbindlich in die Qualitätsentwicklung der Schulen einbinden', '{2302}', 10125, 2, 3, null, 'Aktives Eingreifen von Lehrkräften hängt mit weniger Viktimisierung zusammen; eine kontrollierte Studie zu einem kurzen Lehrkräftetraining fand aber keine Änderung von Verhalten und Mobbing.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=89', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10603241/', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10191, 23, 14, 'MV', 'Jede Schule erhält eine Kraft für Schulsozialarbeit, die soziale Konflikte lösen hilft', '{2302}', 10122, 2, 2, null, 'Fachkräfte vor Ort können Konflikte und Mobbingfälle früh bearbeiten und Lehrkräfte unterstützen; belastbare Wirkungsstudien fehlen weitgehend, und Fachkräfte sind knapp.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=97', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10192, 23, 14, 'MV', 'Schülerinnen und Schüler mit psychischer Stärke durch die Schulzeit begleiten, mit Fachkräften und festen Strukturen', '{2304}', 10123, 1, 2, null, 'Hilft Belasteten, lindert aber Folgen statt den Leistungsdruck selbst; gezielte Hilfen wirken, universelle Programme (etwa Achtsamkeit) zeigten in großen Studien keinen Effekt.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=101', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9340028/', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10193, 23, 14, 'ST', 'Verbindliches Qualifizierungsprogramm mit pädagogischer Schulung, Fortbildungen und Mentoring für Seiteneinsteiger in den Lehrerberuf', '{2302}', 10126, 1, 3, null, 'Mehr Praxis und Fortbildung können die Handlungssicherheit im Klassenraum stärken; Mobbing und Konflikte sind nicht genannt, ein Effekt auf das Eingreifen ist kaum untersucht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=30', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10194, 23, 14, 'ST', 'Diskriminierung in Jugendarbeit und Schule entgegenwirken, mit Aufklärung für Toleranz und Akzeptanz werben', '{2301}', 10115, 1, 3, null, 'Zielt auf abwertende Haltungen, die Ausgrenzung begünstigen; Programme zur Vorurteilsreduktion zeigen aber oft nur kleine, kurzlebige Effekte, eine Wirkung auf Mobbing ist kaum nachgewiesen.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=37', null, 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10195, 23, 15, null, 'Stärkung der Disziplinarrechte und der rechtlichen Sicherheit von Lehrkräften und Schulen', '{2301,2302}', null, 1, 1, null, 'Mehr Disziplinarrechte können Eingreifen erleichtern, strafende Ansätze allein zeigen aber wenig Wirkung aufs Schulklima; Schulrecht ist Ländersache.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=162', null, 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10196, 23, 15, 'BE', 'Konsequentes Ahnden von übergriffigem Verhalten gegen Mitschüler und Lehrer; verbindliches Meldeverfahren und Einschalten der Polizei bei Gewalt an Schulen', '{2301,2302}', 10120, 2, 3, null, 'Klare Regeln und verlässliche Reaktionen gelten als wirksame Bestandteile von Anti-Mobbing-Programmen; rein strafende Ahndung ohne Prävention zeigt dagegen wenig Wirkung auf das Schulklima.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=31', null, 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10197, 23, 15, 'BE', 'Schulausschluss, wenn eine ernstliche Gefahr für andere Schüler besteht', '{2301}', 10121, 1, 3, null, 'Schützt Mitschüler kurzfristig vor gewalttätigen Einzelnen; Studien zu Ausschlüssen finden aber keine Verbesserung von Schulklima und Verhalten, teils mehr Folgeprobleme bei den Ausgeschlossenen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=31', null, 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10198, 23, 15, 'BE', 'Alternative Beschulungsformen für fremdgefährdende Kinder und Jugendliche', '{2301}', 10121, 1, 3, null, 'Schützt Mitschüler kurzfristig vor gewalttätigen Einzelnen; Studien zu Ausschlüssen finden aber keine Verbesserung von Schulklima und Verhalten, teils mehr Folgeprobleme bei den Ausgeschlossenen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=31', null, 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10199, 23, 15, 'BE', 'Einführung von Schulkleidung, damit die Herkunft im Schulalltag weniger in den Vordergrund tritt', '{2301}', null, 1, 3, null, 'Soll Statusunterschiede als Anlass für Ausgrenzung mindern; größere Studien finden keinen Rückgang von Mobbing, nur Befragungen einzelner Schulen berichten Vorteile.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=29', null, 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10200, 23, 15, 'BE', 'Lehrkräfteausbildung mit Schwerpunkt auf Klassenführung und Stressmanagement', '{2302}', 10125, 2, 3, null, 'Aktives Eingreifen von Lehrkräften hängt mit weniger Viktimisierung zusammen; eine kontrollierte Studie zu einem kurzen Lehrkräftetraining fand aber keine Änderung von Verhalten und Mobbing.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=39', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10603241/', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10201, 23, 15, 'MV', 'Lehrkräfte sollen ihre Sanktionsmöglichkeiten gesetzlich erhalten; bei Gewalt- und Drogendelikten sollen Schulverweise schneller erfolgen.', '{2301}', 10121, 1, 3, null, 'Schützt Mitschüler kurzfristig vor gewalttätigen Einzelnen; Studien zu Ausschlüssen finden aber keine Verbesserung von Schulklima und Verhalten, teils mehr Folgeprobleme bei den Ausgeschlossenen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=32', null, 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10202, 23, 15, 'MV', 'Schulsozialarbeit wird als Landesaufgabe etabliert; die Zahl der Schulpsychologen soll dem Bedarf angepasst werden.', '{2301,2302}', 10122, 2, 2, null, 'Fachkräfte vor Ort können Konflikte und Mobbingfälle früh bearbeiten und Lehrkräfte unterstützen; belastbare Wirkungsstudien fehlen weitgehend, und Fachkräfte sind knapp.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=25', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10203, 23, 15, 'MV', 'Vorschaltklassen, in denen Kinder mit Sprachdefiziten bei Bedarf Sprachkompetenz und grundlegendes Sozialverhalten vermittelt bekommen.', '{2301}', null, 1, 2, null, 'Vermittlung von Sozialverhalten kann Konflikte mindern; getrennte Klassen können aber Ausgrenzung verstärken, eine Wirkung auf Mobbing ist kaum untersucht.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=26', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10204, 23, 15, 'ST', 'Gewalttäter sollen nach überarbeiteten Ordnungsmaßnahmen schneller von der Schule verwiesen werden können; bei Wiederholung Überweisung an eine Spezialschule.', '{2301}', 10121, 1, 3, null, 'Schützt Mitschüler kurzfristig vor gewalttätigen Einzelnen; Studien zu Ausschlüssen finden aber keine Verbesserung von Schulklima und Verhalten, teils mehr Folgeprobleme bei den Ausgeschlossenen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=89', null, 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10205, 23, 15, 'ST', 'Vernetzung von Schulen und Staatsanwaltschaften, damit jede Straftat strafmündiger Schüler vor Gericht kommt.', '{2301}', null, 1, 1, null, 'Kann Übergriffe als nicht hinnehmbar markieren; Strafverfahren wirken spät, und Diversion nach Jugendgerichtsgesetz ist Bundesrecht, eine Anklage jeder Tat kann das Land nicht vorgeben.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=89', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10206, 23, 15, 'ST', 'Privater Wachdienst auf dem Schulhof, unterstellt dem Schulleiter, bei Bedarf einzurichten.', '{2301}', null, 1, 2, null, 'Mehr Aufsicht auf dem Schulhof kann Übergriffe dort mindern; private Wachleute haben aber keine pädagogische Rolle und kaum Befugnisse, Wirkung auf Mobbing ist unbelegt.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=88', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10207, 23, 15, 'ST', 'Erweiterte Appellationsrechte für Eltern und Schüler bei Fehlverhalten von Lehrkräften und eine Beschwerdestelle am Bildungsministerium.', '{2302}', 10128, 1, 3, null, 'Bietet Betroffenen einen Weg, wenn die Schule nicht handelt; wirkt aber nachgelagert im Einzelfall, Effekte auf Mobbing sind kaum untersucht.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=86', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10208, 23, 16, null, 'Hausaufgaben abschaffen; das Einüben und Festigen soll in der Schule stattfinden.', '{2304}', null, 1, 1, null, 'Weniger Hausaufgaben können Lernangst und Druck mindern (Querschnittsdaten), der Nutzen von Hausaufgaben ist uneinheitlich belegt; über Hausaufgaben entscheiden allein die Länder.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', 'https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2023.1130274/full', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10209, 23, 16, null, 'Schulpsychologische und sozialarbeiterische Fachkräfte dauerhaft an jeder Schule verfügbar machen.', '{2304}', 10124, 1, 2, null, 'Bund kann mit Programmen beitragen, dauerhaftes Personal an Schulen liegt bei den Ländern; lindert Folgen von Druck, universelle Angebote zeigen gemischte Ergebnisse.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=39', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9340028/', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10210, 23, 17, 'BE', 'Flächendeckende Präventions- und Anti-Gewaltprogramme an Schulen einführen', '{2301}', 10113, 3, 2, null, 'Setzt direkt an Klassennormen an; Meta-Analysen zeigen eine Senkung von Mobbing um rund ein Fünftel. Flächendeckende Einführung braucht Fortbildung, Unterrichtszeit und Qualitätssicherung über Jahre.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', 'https://doi.org/10.1002/cl2.1143', 'belegt', '2026-10-20', false, true, 'blind', null),
  (10211, 23, 17, 'BE', 'Mehr Sozialarbeit an Schulen; Prävention statt Repression bei Gewalt unter Minderjährigen', '{2302,2301}', 10122, 2, 2, null, 'Fachkräfte vor Ort können Konflikte und Mobbingfälle früh bearbeiten und Lehrkräfte unterstützen; belastbare Wirkungsstudien fehlen weitgehend, und Fachkräfte sind knapp.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10212, 23, 17, 'BE', 'Fortbildungsangebote für Lehrkräfte, Sozialarbeit und Polizei gegen Cybermobbing erweitern und verbessern', '{2302}', 10125, 2, 3, null, 'Aktives Eingreifen von Lehrkräften hängt mit weniger Viktimisierung zusammen; eine kontrollierte Studie zu einem kurzen Lehrkräftetraining fand aber keine Änderung von Verhalten und Mobbing.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10603241/', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10213, 23, 17, 'BE', 'Frühere Intervention bei Gewalt in Schulen und intensive soziale Betreuung von Mehrfachtätern', '{2302}', null, 1, 3, null, 'Früheres Eingreifen setzt direkt am Handeln der Schule an; die Zusage nennt aber kein Verfahren, und die Betreuung von Mehrfachtätern erreicht nur einen kleinen Teil der Fälle.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10214, 23, 17, 'BE', 'Wiedereinführung einer verbindlichen Vorschulphase, die soziales Lernen fördert', '{2301}', 10117, 1, 2, null, 'Soziales Lernen ist nur ein Nebenziel von Vorschule und Ganztag; ein Effekt auf Mobbing in der Schule ist kaum untersucht. Ausbau braucht Personal und Räume.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=14', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10215, 23, 17, 'MV', 'Gewaltschutz, Prävention und soziales Lernen als feste Bestandteile schulischer Bildung ausbauen.', '{2301}', 10113, 3, 2, null, 'Setzt direkt an Klassennormen an; Meta-Analysen zeigen eine Senkung von Mobbing um rund ein Fünftel. Flächendeckende Einführung braucht Fortbildung, Unterrichtszeit und Qualitätssicherung über Jahre.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', 'https://doi.org/10.1002/cl2.1143', 'belegt', '2026-10-20', false, true, 'blind', null),
  (10216, 23, 17, 'MV', 'Schulen mit multiprofessionellen Teams (u. a. Sozialarbeit, Schulpsychologie) ausstatten, um psychischen Problemen und Gewalt vorzubeugen.', '{2301,2302,2304}', 10122, 2, 2, null, 'Fachkräfte vor Ort können Konflikte und Mobbingfälle früh bearbeiten und Lehrkräfte unterstützen; belastbare Wirkungsstudien fehlen weitgehend, und Fachkräfte sind knapp.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10217, 23, 17, 'MV', 'Verbindliche Klassenleiterstunde und feste Sprechzeiten für Klassenleitungen.', '{2301}', 10116, 1, 3, null, 'Kann Zusammenhalt und Klassennormen positiv beeinflussen und Konflikte früh sichtbar machen; eigenständige Wirkung auf Mobbing ist kaum untersucht.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10218, 23, 17, 'MV', 'Mehr Klassennachmittage, gemeinsame Unternehmungen und Aktionen an Schulen.', '{2301}', 10116, 1, 3, null, 'Kann Zusammenhalt und Klassennormen positiv beeinflussen und Konflikte früh sichtbar machen; eigenständige Wirkung auf Mobbing ist kaum untersucht.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10219, 23, 17, 'MV', 'Kleinere Klassen mit höchstens 24 Schülerinnen und Schülern, unter anderem für Resilienz und soziale Kompetenzen.', '{2304,2301}', null, 1, 1, null, 'Kleinere Klassen senkten Mobbing in manchen Studien (etwa Grundschule Japan), in anderen nicht; zusätzliche Lehrkräfte fehlen absehbar.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=48', 'https://www.rieti.go.jp/en/publications/summary/17030016.html', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10220, 23, 17, 'MV', 'Verbindliche Sucht- und Gesundheitsprävention in Schulen, altersgerecht und alltagsnah, mit Stärkung von Lebens-, Sozial- und Resilienzkompetenzen.', '{2304,2301}', null, 1, 3, null, 'Lebenskompetenzprogramme können Sozial- und Bewältigungsfähigkeiten stärken; der Schwerpunkt liegt auf Sucht- und Gesundheitsprävention, Mobbing und Leistungsdruck werden nur am Rand berührt.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=63', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10221, 23, 17, 'MV', 'Schultage nicht weiter verlängern, stattdessen Hausaufgabenbetreuung anbieten, damit der Nachmittag frei bleibt.', '{2304}', 10131, 1, 2, null, 'Mehr Hausaufgabenzeit geht mit mehr Lernangst einher (Querschnittsdaten); der Nutzen von Hausaufgaben ist uneinheitlich belegt. Betreute Lernzeit braucht Personal.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', 'https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2023.1130274/full', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10222, 23, 17, 'MV', 'Verpflichtende, praxisnahe Fortbildungen für Lehrkräfte, im Rahmen verbesserter Arbeitsbedingungen.', '{2302}', 10126, 1, 3, null, 'Mehr Praxis und Fortbildung können die Handlungssicherheit im Klassenraum stärken; Mobbing und Konflikte sind nicht genannt, ein Effekt auf das Eingreifen ist kaum untersucht.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=47', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10223, 23, 17, 'ST', 'Verbindlicher landesweiter Personalschlüssel für Schulsozialarbeit und Schulpsychologie; jede Schule mindestens eine Schulsozialarbeitsstelle', '{2301,2302}', 10122, 2, 2, null, 'Fachkräfte vor Ort können Konflikte und Mobbingfälle früh bearbeiten und Lehrkräfte unterstützen; belastbare Wirkungsstudien fehlen weitgehend, und Fachkräfte sind knapp.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=47', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10224, 23, 17, 'ST', 'Lehramtsausbildung: Theorie und Praxis im Studium besser verzahnen, damit Absolventen im Beruf bestehen', '{2302}', 10126, 1, 3, null, 'Mehr Praxis und Fortbildung können die Handlungssicherheit im Klassenraum stärken; Mobbing und Konflikte sind nicht genannt, ein Effekt auf das Eingreifen ist kaum untersucht.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=52', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10225, 23, 17, 'ST', 'Sozialpsychiatrischen Dienst ausbauen und stärker in Jugend- und Schularbeit einbinden', '{2304}', 10123, 1, 2, null, 'Hilft Belasteten, lindert aber Folgen statt den Leistungsdruck selbst; gezielte Hilfen wirken, universelle Programme (etwa Achtsamkeit) zeigten in großen Studien keinen Effekt.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=59', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9340028/', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10226, 23, 17, 'ST', 'Längeres gemeinsames Lernen als Antwort auf Überforderung und Leistungsdruck an Schulen', '{2304}', 10130, 2, 2, null, 'Verbindliche Übergangsentscheidungen erhöhen nachweislich Noten- und Zukunftsangst in Klasse 4; zugleich steigen dort die Leistungen. Strukturreformen brauchen mehrere Jahre.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=45', 'https://www.zew.de/en/press/latest-press-releases/binding-teachers-recommendation-for-secondary-school-track-increases-pupils-achievement-but-also-their-stress-levels', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10325, 23, 13, 'ST', 'Landesprogramm gegen Mobbing; Schulklima und Schulsozialarbeit als Bausteine der Prävention.', '{2301,2302}', 10112, 2, 3, null, 'Schulische Anti-Mobbing-Programme senken Mobbing und Viktimisierung nachweislich, wenn auch moderat; die Zusagen bleiben unbestimmt (fördern, stärken) und legen weder Reichweite noch Programmstandard fest.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=63', 'https://doi.org/10.1002/cl2.1143', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10326, 23, 13, 'ST', 'Unabhängige landesweite Ombudsstelle für Schulen, an die sich Schüler*innen, Eltern und Lehrkräfte bei Diskriminierung und Übergriffen anonym wenden können.', '{2302}', 10128, 1, 3, null, 'Bietet Betroffenen einen Weg, wenn die Schule nicht handelt; wirkt aber nachgelagert im Einzelfall, Effekte auf Mobbing sind kaum untersucht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=64', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10327, 23, 13, 'ST', 'Verbindliche regelmäßige Fortbildungen für Lehrkräfte zu Diskriminierung und Übergriffen.', '{2302}', 10125, 2, 3, null, 'Aktives Eingreifen von Lehrkräften hängt mit weniger Viktimisierung zusammen; eine kontrollierte Studie zu einem kurzen Lehrkräftetraining fand aber keine Änderung von Verhalten und Mobbing.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=64', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10603241/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10328, 23, 13, 'ST', 'Mehr Mitbestimmung von Schüler*innen durch Klassenräte und Schüler*innenparlamente.', '{2301}', 10116, 1, 3, null, 'Kann Zusammenhalt und Klassennormen positiv beeinflussen und Konflikte früh sichtbar machen; eigenständige Wirkung auf Mobbing ist kaum untersucht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=64', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10329, 23, 13, 'ST', 'Stressmanagement, Achtsamkeit und Entspannung als Bestandteil des Sportunterrichts.', '{2304}', 10322, 1, 3, null, 'Schulische Präventionsprogramme senken Angst und Depressivität nur schwach, universelle Angebote weniger als gezielte; lindert Folgen, statt den Leistungsdruck selbst zu senken. Curricula sind Landessache.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=56', 'https://openresearch-repository.anu.edu.au/items/f894e732-2981-4864-b78f-eafbf446aba1', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10330, 23, 13, 'ST', 'Benotungen im Schulbetrieb deutlich verringern und in Neigungs- und Talentfächern abschaffen; stattdessen dialogorientierte Rückmeldungen.', '{2304}', 10321, 2, 3, null, 'Benotete Stunden gehen in Studien mit mehr Angst und weniger Motivation einher; in Langzeitvergleichen ohne Noten zeigte sich aber kaum besseres Wohlbefinden, Druck kann sich auf spätere Abschlüsse verlagern.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=60', 'https://publinova.nl/product/performance-grading-and-motivational-functioning-and-fear-in-physical-education', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10331, 23, 13, 'ST', 'Sitzenbleiben soll im Wesentlichen eine freiwillige Entscheidung von Schüler*innen und Eltern sein.', '{2304}', 10320, 1, 3, null, 'Nimmt die Drohung der Nichtversetzung, und Sitzenbleiben verbessert Leistungen laut Forschung nicht; zum Wohlbefinden sind Befunde uneinheitlich (teils Belastung, teils positive Effekte), betroffen ist ein kleiner Teil.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=60', 'https://www.bertelsmann-stiftung.de/de/publikationen/publikation/did/klassenwiederholungen-teuer-und-unwirksam', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10332, 23, 13, 'ST', 'Stärkung der flexiblen Schuleingangsphase mit altersgemischten Gruppen, ohne Leistungsdruck durch Sitzenbleiben.', '{2304}', 10320, 1, 3, null, 'Nimmt die Drohung der Nichtversetzung, und Sitzenbleiben verbessert Leistungen laut Forschung nicht; zum Wohlbefinden sind Befunde uneinheitlich (teils Belastung, teils positive Effekte), betroffen ist ein kleiner Teil.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=60', 'https://www.bertelsmann-stiftung.de/de/publikationen/publikation/did/klassenwiederholungen-teuer-und-unwirksam', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10333, 23, 13, 'ST', 'Abitur wieder nach 13 Schuljahren (G9), damit mehr Zeit für persönliche Entwicklung bleibt.', '{2304}', null, 1, 2, null, 'Eine Studie fand unter G8 mehr Stress bei Mädchen, andere keine gesundheitlichen Unterschiede zu G9; die Umstellung dauert mehrere Jahre und braucht zusätzliche Lehrkräfte.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=60', 'https://www.diw.de/de/diw_01.c.497179.de/publikationen/roundup/2015_0057/empirische_befunde_zu_auswirkungen_der_g8-schulzeitverkuerzung.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10334, 23, 16, 'BE', 'Unabhängige Beschwerdestelle für Schüler*innen und Eltern bei Diskriminierung, Mobbing und Gewalt an Schulen', '{2302}', 10128, 1, 3, null, 'Bietet Betroffenen einen Weg, wenn die Schule nicht handelt; wirkt aber nachgelagert im Einzelfall, Effekte auf Mobbing sind kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=162', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10335, 23, 16, 'BE', 'Schulsozialarbeit strukturell stärken, um Ausgrenzung und Gewalt frühzeitig entgegenzuwirken', '{2301,2302}', 10122, 2, 2, null, 'Fachkräfte vor Ort können Konflikte und Mobbingfälle früh bearbeiten und Lehrkräfte unterstützen; belastbare Wirkungsstudien fehlen weitgehend, und Fachkräfte sind knapp.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=281', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10336, 23, 16, 'BE', 'Ziffernnoten bis einschließlich Klasse 9 durch mündliche und schriftliche Rückmeldungen zum Leistungsstand ersetzen', '{2304}', 10321, 2, 3, null, 'Benotete Stunden gehen in Studien mit mehr Angst und weniger Motivation einher; in Langzeitvergleichen ohne Noten zeigte sich aber kaum besseres Wohlbefinden, Druck kann sich auf spätere Abschlüsse verlagern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=168', 'https://publinova.nl/product/performance-grading-and-motivational-functioning-and-fear-in-physical-education', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10337, 23, 16, 'BE', 'Hausaufgaben abbauen', '{2304}', null, 1, 3, null, 'Mehr Hausaufgabenzeit hängt in Querschnittsdaten mit mehr Lernangst zusammen, ursächlich ist das nicht belegt; Abbau ist ohne Zusatzpersonal möglich, der Umfang bleibt unbestimmt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=168', 'https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2023.1130274/full', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10338, 23, 16, 'BE', 'Landesprogramm Psychologie an Schulen mit einer Psychologin oder einem Psychologen auf 800 Schüler*innen', '{2304}', 10123, 1, 2, null, 'Hilft Belasteten, lindert aber Folgen statt den Leistungsdruck selbst; gezielte Hilfen wirken, universelle Programme (etwa Achtsamkeit) zeigten in großen Studien keinen Effekt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=158', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9340028/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10339, 23, 16, 'BE', 'Selbstregulationskompetenzen stärken; mentale Gesundheit in schulinterne Curricula und Peer-to-Peer-Programme aufnehmen', '{2304}', 10322, 1, 3, null, 'Schulische Präventionsprogramme senken Angst und Depressivität nur schwach, universelle Angebote weniger als gezielte; lindert Folgen, statt den Leistungsdruck selbst zu senken. Curricula sind Landessache.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=158', 'https://openresearch-repository.anu.edu.au/items/f894e732-2981-4864-b78f-eafbf446aba1', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10340, 23, 16, 'BE', 'Probeunterricht beim Übergang an weiterführende Schulen abschaffen', '{2304}', 10324, 1, 3, null, 'Verbindliche Übergangsentscheidungen erhöhen nachweislich Sorgen in Klasse 4, zugleich steigen dort die Leistungen; die Maßnahmen lockern nur einzelne Hürden, Druck kann sich auf später verlagern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=161', 'https://www.zew.de/en/press/latest-press-releases/binding-teachers-recommendation-for-secondary-school-track-increases-pupils-achievement-but-also-their-stress-levels', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10341, 23, 16, 'BE', 'Bei der Schulformempfehlung Stärken stärker würdigen und pädagogischer Einschätzung der Klassenkonferenzen mehr Gewicht geben', '{2304}', 10324, 1, 3, null, 'Verbindliche Übergangsentscheidungen erhöhen nachweislich Sorgen in Klasse 4, zugleich steigen dort die Leistungen; die Maßnahmen lockern nur einzelne Hürden, Druck kann sich auf später verlagern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=161', 'https://www.zew.de/en/press/latest-press-releases/binding-teachers-recommendation-for-secondary-school-track-increases-pupils-achievement-but-also-their-stress-levels', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10342, 23, 16, 'BE', 'Sitzenbleiben auch an Gymnasien abschaffen', '{2304}', 10320, 1, 3, null, 'Nimmt die Drohung der Nichtversetzung, und Sitzenbleiben verbessert Leistungen laut Forschung nicht; zum Wohlbefinden sind Befunde uneinheitlich (teils Belastung, teils positive Effekte), betroffen ist ein kleiner Teil.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=162', 'https://www.bertelsmann-stiftung.de/de/publikationen/publikation/did/klassenwiederholungen-teuer-und-unwirksam', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10343, 23, 16, 'BE', 'Überfüllte und veraltete Lehrpläne entrümpeln', '{2304}', 10129, 1, 3, null, 'Weniger Stoff und Fächer können Lernlast senken; ob der Leistungsdruck dadurch spürbar sinkt, hängt von Prüfungen und Bewertung ab und ist kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=157', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10344, 23, 16, 'BE', 'Rückzugsorte für Schüler*innen ohne Bewertung an Schulen; Schulclubs fördern', '{2304}', 10323, 1, 2, null, 'Kann Erholung im Schulalltag ermöglichen; berührt den Leistungsdruck nur am Rand, Wirkung kaum untersucht, und Räume fehlen an vielen Schulen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=164', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10345, 23, 16, 'BE', 'Antidiskriminierungs- und Mobbingbeauftragte der Bildungsverwaltung in Stelle und Einfluss stärken', '{2302}', 10128, 1, 3, null, 'Bietet Betroffenen einen Weg, wenn die Schule nicht handelt; wirkt aber nachgelagert im Einzelfall, Effekte auf Mobbing sind kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=162', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10346, 23, 16, 'BE', 'Außerschulische Präventions- und Empowermentangebote an Schulen, auch zu Mobbing- und Gewaltprävention, absichern und verstetigen', '{2301}', 10112, 2, 3, null, 'Schulische Anti-Mobbing-Programme senken Mobbing und Viktimisierung nachweislich, wenn auch moderat; die Zusagen bleiben unbestimmt (fördern, stärken) und legen weder Reichweite noch Programmstandard fest.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=163', 'https://doi.org/10.1002/cl2.1143', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10347, 23, 16, 'MV', 'Klassenleiterstunden verpflichtend machen und als Klassenrat gemeinsam mit allen Schüler:innen gestalten', '{2301}', 10116, 1, 3, null, 'Kann Zusammenhalt und Klassennormen positiv beeinflussen und Konflikte früh sichtbar machen; eigenständige Wirkung auf Mobbing ist kaum untersucht.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10348, 23, 16, 'MV', 'Eigenes Schulfach „Beziehungen, Sexualkunde und Gesundheit“ nach britischem Vorbild einführen', '{2301}', null, 1, 2, null, 'Ein Fach zu Beziehungen kann soziales Lernen und respektvollen Umgang fördern; Mobbing ist nicht genannt, eine Wirkung kaum untersucht, und ein neues Fach braucht Stundentafel und Lehrkräfte.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=6', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10349, 23, 16, 'MV', 'Leistungskontrollen begrenzen: höchstens zwei Klausuren oder Tests pro Woche', '{2304}', null, 1, 3, null, 'Begrenzt Prüfungsballungen und damit Belastungsspitzen; die Gesamtmenge an Leistungskontrollen bleibt gleich, eine Wirkung solcher Obergrenzen ist kaum untersucht.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=6', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10350, 23, 16, 'MV', 'Leitlinien für die Pausengestaltung an Schulen und Ruhe- und Gemeinschaftsräume bereitstellen', '{2304}', 10323, 1, 2, null, 'Kann Erholung im Schulalltag ermöglichen; berührt den Leistungsdruck nur am Rand, Wirkung kaum untersucht, und Räume fehlen an vielen Schulen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=6', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10351, 23, 16, 'MV', 'Benotung in Kunst, Musik und Sport abschaffen, außer wenn die Fächer als Leistungskurse belegt sind', '{2304}', null, 1, 3, null, 'Benotung im Sport geht in Studien mit mehr Angst und weniger Motivation einher; die Maßnahme betrifft aber nur Nebenfächer, der Druck in den Hauptfächern bleibt.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=6', 'https://publinova.nl/product/performance-grading-and-motivational-functioning-and-fear-in-physical-education', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10352, 23, 16, 'MV', 'Resilienzförderung und Lerntrainings in die Rahmenpläne aufnehmen', '{2304}', 10322, 1, 3, null, 'Schulische Präventionsprogramme senken Angst und Depressivität nur schwach, universelle Angebote weniger als gezielte; lindert Folgen, statt den Leistungsdruck selbst zu senken. Curricula sind Landessache.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=6', 'https://openresearch-repository.anu.edu.au/items/f894e732-2981-4864-b78f-eafbf446aba1', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10353, 23, 16, 'MV', 'Queeres Leben im Rahmenplan von Schulen verankern, etwa in Sozialkunde, Biologie und Geschichte', '{2301}', 10115, 1, 3, null, 'Zielt auf abwertende Haltungen, die Ausgrenzung begünstigen; Programme zur Vorurteilsreduktion zeigen aber oft nur kleine, kurzlebige Effekte, eine Wirkung auf Mobbing ist kaum nachgewiesen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=16', null, 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10354, 23, 16, 'ST', 'Am Ende der Grundschulzeit keine Schullaufbahnempfehlung mehr; Eltern erhalten nur Beratung zur Schulwahl.', '{2304}', 10324, 1, 3, null, 'Verbindliche Übergangsentscheidungen erhöhen nachweislich Sorgen in Klasse 4, zugleich steigen dort die Leistungen; die Maßnahmen lockern nur einzelne Hürden, Druck kann sich auf später verlagern.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=31', 'https://www.zew.de/en/press/latest-press-releases/binding-teachers-recommendation-for-secondary-school-track-increases-pupils-achievement-but-also-their-stress-levels', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10355, 23, 17, null, 'Social-Media-Gesetz nach australischem Vorbild, um Kinder auf Plattformen zu schützen', '{2303}', 10132, 1, 2, null, 'Plattformpflichten können Kinder vor Angriffen schützen; Wirkung auf Cybermobbing ist nicht belegt, Altersprüfungen werden umgangen, und vieles hängt vom EU-Rahmen (DSA) ab.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', null, 'offen', '2026-10-21', false, true, 'blind', null);

